"""
Authentication Token Factories

Generates various authentication tokens (JWT, OAuth2, API keys)
in valid, expired, and invalid states for testing authentication flows.
"""

import base64
import hashlib
import hmac
import json
import random
import secrets
import time
import uuid
from datetime import datetime, timedelta
from typing import Any, Dict, Optional

from faker import Faker

fake = Faker()


class AuthTokenFactory:
    """Base factory for authentication tokens"""

    @staticmethod
    def generate_random_secret(length: int = 32) -> str:
        """Generate cryptographically secure random secret"""
        return secrets.token_urlsafe(length)

    @staticmethod
    def hash_token(token: str, algorithm: str = "sha256") -> str:
        """Hash token for storage"""
        return hashlib.new(algorithm, token.encode()).hexdigest()


class JWTTokenFactory(AuthTokenFactory):
    """Factory for JWT tokens"""

    SECRET_KEY = "test-secret-key-do-not-use-in-production"

    @staticmethod
    def create_valid_token(
        user_id: Optional[str] = None,
        expiry_hours: int = 24,
        scopes: Optional[list] = None,
    ) -> str:
        """Generate valid JWT token"""
        now = int(time.time())
        payload = {
            "sub": user_id or str(uuid.uuid4()),
            "iat": now,
            "exp": now + (expiry_hours * 3600),
            "jti": str(uuid.uuid4()),
            "type": "access",
            "scopes": scopes or ["read", "write"],
            "user": {
                "id": user_id or str(uuid.uuid4()),
                "username": fake.user_name(),
                "email": fake.email(),
            },
        }

        # Mock JWT encoding (not cryptographically secure, for testing only)
        header = {"alg": "HS256", "typ": "JWT"}
        header_b64 = base64.urlsafe_b64encode(json.dumps(header).encode()).decode().rstrip("=")
        payload_b64 = base64.urlsafe_b64encode(json.dumps(payload).encode()).decode().rstrip("=")

        # Mock signature
        message = f"{header_b64}.{payload_b64}"
        signature = base64.urlsafe_b64encode(
            hmac.new(
                JWTTokenFactory.SECRET_KEY.encode(),
                message.encode(),
                hashlib.sha256,
            ).digest()
        ).decode().rstrip("=")

        return f"{header_b64}.{payload_b64}.{signature}"

    @staticmethod
    def create_expired_token(expired_hours: int = 24) -> str:
        """Generate expired JWT token"""
        now = int(time.time())
        payload = {
            "sub": str(uuid.uuid4()),
            "iat": now - (expired_hours * 3600) - 3600,
            "exp": now - (expired_hours * 3600),
            "jti": str(uuid.uuid4()),
            "type": "access",
        }

        header = {"alg": "HS256", "typ": "JWT"}
        header_b64 = base64.urlsafe_b64encode(json.dumps(header).encode()).decode().rstrip("=")
        payload_b64 = base64.urlsafe_b64encode(json.dumps(payload).encode()).decode().rstrip("=")

        message = f"{header_b64}.{payload_b64}"
        signature = base64.urlsafe_b64encode(
            hmac.new(
                JWTTokenFactory.SECRET_KEY.encode(),
                message.encode(),
                hashlib.sha256,
            ).digest()
        ).decode().rstrip("=")

        return f"{header_b64}.{payload_b64}.{signature}"

    @staticmethod
    def create_invalid_token() -> str:
        """Generate invalid JWT token"""
        return f"{fake.sha256()[:22]}.{fake.sha256()[:32]}.{fake.sha256()[:43]}"

    @staticmethod
    def create_malformed_token() -> str:
        """Generate malformed JWT token"""
        return fake.sha256()  # Missing dots

    @staticmethod
    def create_token_with_invalid_signature() -> str:
        """Generate JWT token with invalid signature"""
        header = {"alg": "HS256", "typ": "JWT"}
        payload = {
            "sub": str(uuid.uuid4()),
            "iat": int(time.time()),
            "exp": int(time.time()) + 3600,
        }

        header_b64 = base64.urlsafe_b64encode(json.dumps(header).encode()).decode().rstrip("=")
        payload_b64 = base64.urlsafe_b64encode(json.dumps(payload).encode()).decode().rstrip("=")

        # Invalid signature
        signature = fake.sha256()[:43]

        return f"{header_b64}.{payload_b64}.{signature}"


class OAuth2TokenFactory(AuthTokenFactory):
    """Factory for OAuth2 tokens"""

    @staticmethod
    def create_access_token(
        token_type: str = "Bearer",
        expiry_seconds: int = 3600,
    ) -> Dict[str, Any]:
        """Generate OAuth2 access token response"""
        return {
            "access_token": secrets.token_urlsafe(32),
            "token_type": token_type,
            "expires_in": expiry_seconds,
            "expires_at": int(time.time()) + expiry_seconds,
            "scope": "read write admin",
            "refresh_token": secrets.token_urlsafe(32),
        }

    @staticmethod
    def create_expired_access_token() -> Dict[str, Any]:
        """Generate expired OAuth2 access token"""
        return {
            "access_token": secrets.token_urlsafe(32),
            "token_type": "Bearer",
            "expires_in": -3600,
            "expires_at": int(time.time()) - 3600,
            "scope": "read write",
        }

    @staticmethod
    def create_refresh_token() -> Dict[str, Any]:
        """Generate OAuth2 refresh token"""
        return {
            "refresh_token": secrets.token_urlsafe(32),
            "token_type": "refresh",
            "expires_in": 2592000,  # 30 days
            "scope": "offline_access",
        }

    @staticmethod
    def create_authorization_code() -> str:
        """Generate OAuth2 authorization code"""
        return secrets.token_urlsafe(24)


class APIKeyFactory(AuthTokenFactory):
    """Factory for API keys"""

    @staticmethod
    def create_api_key(prefix: str = "ak", length: int = 32) -> str:
        """Generate API key with prefix"""
        return f"{prefix}_{secrets.token_urlsafe(length)}"

    @staticmethod
    def create_api_key_pair() -> Dict[str, str]:
        """Generate API key ID and secret pair"""
        key_id = f"akid_{secrets.token_urlsafe(16)}"
        key_secret = secrets.token_urlsafe(32)
        return {
            "key_id": key_id,
            "key_secret": key_secret,
            "key_hash": AuthTokenFactory.hash_token(key_secret),
        }

    @staticmethod
    def create_github_token() -> str:
        """Generate GitHub-style personal access token"""
        return f"ghp_{secrets.token_urlsafe(36)}"

    @staticmethod
    def create_gitlab_token() -> str:
        """Generate GitLab-style personal access token"""
        return f"glpat-{secrets.token_urlsafe(20)}"

    @staticmethod
    def create_webhook_secret() -> str:
        """Generate webhook signing secret"""
        return secrets.token_hex(32)


# Edge case tokens
class EdgeCaseTokenFactory:
    """Factory for edge case authentication tokens"""

    @staticmethod
    def create_empty_token() -> str:
        """Generate empty token"""
        return ""

    @staticmethod
    def create_whitespace_token() -> str:
        """Generate whitespace-only token"""
        return "   \t\n  "

    @staticmethod
    def create_special_characters_token() -> str:
        """Generate token with special characters"""
        return "!@#$%^&*(){}[]|\\:;\"'<>,.?/"

    @staticmethod
    def create_sql_injection_token() -> str:
        """Generate SQL injection attempt token"""
        return "' OR '1'='1'; DROP TABLE users; --"

    @staticmethod
    def create_xss_token() -> str:
        """Generate XSS attempt token"""
        return "<script>alert('XSS')</script>"

    @staticmethod
    def create_path_traversal_token() -> str:
        """Generate path traversal attempt token"""
        return "../../../etc/passwd"

    @staticmethod
    def create_null_byte_token() -> str:
        """Generate token with null byte"""
        return f"valid_token\x00malicious_data"

    @staticmethod
    def create_unicode_token() -> str:
        """Generate token with unicode characters"""
        return f"token_日本語_🚀_{secrets.token_urlsafe(16)}"

    @staticmethod
    def create_oversized_token(size_kb: int = 10) -> str:
        """Generate oversized token"""
        return "x" * (size_kb * 1024)


# Token state manager for testing
class TokenStateManager:
    """Manager for tracking token states in tests"""

    def __init__(self):
        self.tokens: Dict[str, Dict[str, Any]] = {}

    def register_token(
        self,
        token: str,
        state: str = "valid",
        metadata: Optional[Dict[str, Any]] = None,
    ):
        """Register token with state"""
        self.tokens[token] = {
            "state": state,
            "created_at": datetime.utcnow(),
            "metadata": metadata or {},
        }

    def get_token_state(self, token: str) -> Optional[str]:
        """Get token state"""
        return self.tokens.get(token, {}).get("state")

    def revoke_token(self, token: str):
        """Revoke token"""
        if token in self.tokens:
            self.tokens[token]["state"] = "revoked"
            self.tokens[token]["revoked_at"] = datetime.utcnow()

    def create_token_set(self) -> Dict[str, str]:
        """Create set of tokens in various states"""
        tokens = {
            "valid": JWTTokenFactory.create_valid_token(),
            "expired": JWTTokenFactory.create_expired_token(),
            "invalid": JWTTokenFactory.create_invalid_token(),
            "malformed": JWTTokenFactory.create_malformed_token(),
        }

        for name, token in tokens.items():
            self.register_token(token, state=name)

        return tokens

"""
API Request and Response Factories

Generates realistic API request payloads and responses for testing
CI/CD webhook integrations, artifact uploads, and API interactions.
"""

import random
import uuid
from datetime import datetime, timedelta
from typing import Any, Dict, List, Optional

from faker import Faker

fake = Faker()


class APIRequestFactory:
    """Factory for generating API request payloads"""

    @staticmethod
    def create_webhook_payload(
        event_type: str = "push",
        repository: Optional[str] = None,
        branch: Optional[str] = None,
        commit_count: int = 1,
    ) -> Dict[str, Any]:
        """Generate GitHub/GitLab-style webhook payload"""
        repo_name = repository or fake.slug()
        branch_name = branch or random.choice(["main", "develop", "feature/test", "hotfix/bug"])

        commits = [
            {
                "id": fake.sha256()[:40],
                "message": fake.sentence(),
                "author": {
                    "name": fake.name(),
                    "email": fake.email(),
                    "username": fake.user_name(),
                },
                "timestamp": fake.iso8601(),
                "added": [f"src/{fake.file_name(extension='py')}" for _ in range(random.randint(0, 3))],
                "modified": [f"tests/{fake.file_name(extension='py')}" for _ in range(random.randint(0, 5))],
                "removed": [f"docs/{fake.file_name(extension='md')}" for _ in range(random.randint(0, 2))],
            }
            for _ in range(commit_count)
        ]

        return {
            "event": event_type,
            "repository": {
                "id": random.randint(1000, 9999999),
                "name": repo_name,
                "full_name": f"{fake.user_name()}/{repo_name}",
                "url": f"https://github.com/{fake.user_name()}/{repo_name}",
                "default_branch": "main",
                "visibility": random.choice(["public", "private", "internal"]),
            },
            "ref": f"refs/heads/{branch_name}",
            "before": fake.sha256()[:40],
            "after": commits[-1]["id"] if commits else fake.sha256()[:40],
            "commits": commits,
            "pusher": {
                "name": fake.name(),
                "email": fake.email(),
            },
            "sender": {
                "login": fake.user_name(),
                "id": random.randint(1000, 9999999),
                "type": "User",
            },
            "created": False,
            "deleted": False,
            "forced": False,
            "compare": f"https://github.com/{fake.user_name()}/{repo_name}/compare/{fake.sha256()[:7]}...{fake.sha256()[:7]}",
        }

    @staticmethod
    def create_artifact_upload_request(
        artifact_type: str = "test-results",
        size_mb: float = 1.5,
    ) -> Dict[str, Any]:
        """Generate artifact upload request payload"""
        return {
            "artifact_id": str(uuid.uuid4()),
            "name": f"{artifact_type}-{fake.slug()}.zip",
            "type": artifact_type,
            "size_bytes": int(size_mb * 1024 * 1024),
            "checksum": {
                "algorithm": "sha256",
                "value": fake.sha256(),
            },
            "metadata": {
                "build_id": str(uuid.uuid4()),
                "job_name": fake.job(),
                "runner": random.choice(["ubuntu-latest", "macos-latest", "windows-latest"]),
                "timestamp": datetime.utcnow().isoformat(),
                "retention_days": random.randint(1, 90),
            },
            "compression": random.choice(["gzip", "zip", "none"]),
        }

    @staticmethod
    def create_test_execution_request(
        test_count: int = 100,
        framework: str = "pytest",
    ) -> Dict[str, Any]:
        """Generate test execution request payload"""
        return {
            "execution_id": str(uuid.uuid4()),
            "framework": framework,
            "configuration": {
                "parallel": random.choice([True, False]),
                "workers": random.randint(1, 8),
                "timeout": random.randint(300, 3600),
                "retries": random.randint(0, 3),
                "fail_fast": random.choice([True, False]),
            },
            "test_suite": {
                "path": "tests/",
                "pattern": f"test_*.{framework}",
                "count": test_count,
                "categories": {
                    "unit": int(test_count * 0.6),
                    "integration": int(test_count * 0.3),
                    "e2e": int(test_count * 0.1),
                },
            },
            "environment": {
                "python_version": random.choice(["3.10", "3.11", "3.12"]),
                "os": random.choice(["ubuntu-22.04", "macos-13", "windows-2022"]),
                "dependencies": [
                    {"name": fake.word(), "version": f"{random.randint(1, 5)}.{random.randint(0, 20)}.{random.randint(0, 10)}"}
                    for _ in range(random.randint(5, 15))
                ],
            },
        }

    @classmethod
    def create_batch(cls, count: int, request_type: str = "webhook") -> List[Dict[str, Any]]:
        """Generate batch of requests"""
        generators = {
            "webhook": cls.create_webhook_payload,
            "artifact": cls.create_artifact_upload_request,
            "test": cls.create_test_execution_request,
        }
        generator = generators.get(request_type, cls.create_webhook_payload)
        return [generator() for _ in range(count)]


class APIResponseFactory:
    """Factory for generating API response payloads"""

    @staticmethod
    def create_success_response(
        data: Optional[Dict[str, Any]] = None,
        status_code: int = 200,
    ) -> Dict[str, Any]:
        """Generate successful API response"""
        return {
            "status": "success",
            "status_code": status_code,
            "data": data or {"message": "Operation completed successfully"},
            "timestamp": datetime.utcnow().isoformat(),
            "request_id": str(uuid.uuid4()),
        }

    @staticmethod
    def create_error_response(
        error_type: str = "validation_error",
        status_code: int = 400,
    ) -> Dict[str, Any]:
        """Generate error API response"""
        error_messages = {
            "validation_error": "Invalid request payload",
            "authentication_error": "Invalid or missing authentication token",
            "authorization_error": "Insufficient permissions",
            "rate_limit_error": "Rate limit exceeded",
            "server_error": "Internal server error",
            "timeout_error": "Request timeout",
        }

        return {
            "status": "error",
            "status_code": status_code,
            "error": {
                "type": error_type,
                "message": error_messages.get(error_type, "Unknown error"),
                "code": f"ERR_{status_code}_{error_type.upper()}",
                "details": {
                    "field": fake.word() if "validation" in error_type else None,
                    "reason": fake.sentence(),
                },
            },
            "timestamp": datetime.utcnow().isoformat(),
            "request_id": str(uuid.uuid4()),
        }

    @staticmethod
    def create_paginated_response(
        items: List[Any],
        page: int = 1,
        per_page: int = 10,
        total: Optional[int] = None,
    ) -> Dict[str, Any]:
        """Generate paginated API response"""
        total_items = total or len(items) * 5
        total_pages = (total_items + per_page - 1) // per_page

        return {
            "status": "success",
            "data": items[:per_page],
            "pagination": {
                "page": page,
                "per_page": per_page,
                "total_items": total_items,
                "total_pages": total_pages,
                "has_next": page < total_pages,
                "has_prev": page > 1,
                "next_page": page + 1 if page < total_pages else None,
                "prev_page": page - 1 if page > 1 else None,
            },
            "timestamp": datetime.utcnow().isoformat(),
        }


# Edge case and boundary value generators
class EdgeCaseAPIFactory:
    """Factory for edge case and boundary value API requests"""

    @staticmethod
    def create_empty_payload() -> Dict[str, Any]:
        """Generate empty payload"""
        return {}

    @staticmethod
    def create_null_values_payload() -> Dict[str, Any]:
        """Generate payload with null values"""
        return {
            "repository": None,
            "commits": None,
            "author": None,
            "timestamp": None,
        }

    @staticmethod
    def create_oversized_payload(size_mb: float = 10.0) -> Dict[str, Any]:
        """Generate oversized payload"""
        return {
            "artifact_id": str(uuid.uuid4()),
            "data": "x" * int(size_mb * 1024 * 1024),  # Oversized data field
            "size_bytes": int(size_mb * 1024 * 1024),
        }

    @staticmethod
    def create_malformed_json() -> str:
        """Generate malformed JSON string"""
        return '{"incomplete": "json", "missing'

    @staticmethod
    def create_special_characters_payload() -> Dict[str, Any]:
        """Generate payload with special characters"""
        return {
            "message": "Test with special chars: <>&\"'`\n\t\r",
            "path": "../../../etc/passwd",  # Path traversal attempt
            "script": "<script>alert('XSS')</script>",
            "sql": "'; DROP TABLE users; --",
            "unicode": "日本語🚀💻Ñoño",
        }

    @staticmethod
    def create_boundary_values() -> Dict[str, Any]:
        """Generate boundary value payload"""
        return {
            "integer_min": -2147483648,
            "integer_max": 2147483647,
            "integer_zero": 0,
            "float_min": float("-inf"),
            "float_max": float("inf"),
            "float_nan": float("nan"),
            "string_empty": "",
            "string_single": "a",
            "string_max": "x" * 65535,
            "array_empty": [],
            "array_single": [1],
            "array_large": list(range(10000)),
        }
